"""
Invitación interactiva "Una cita pendiente" 💌
Ejecutar:  python cita.py
Se abre sola en el navegador (no necesita instalar nada).
Para cerrar: Ctrl + C en la terminal.
"""
import http.server
import socketserver
import threading
import webbrowser

PUERTO = 8000

HTML = r"""<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Una cita pendiente 💌</title>
<link href="https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,400;0,700;1,400;1,600&display=swap" rel="stylesheet">
<style>
:root{--blue:#cfe6ff;--pink:#ffd1e3;--yellow:#fff3b8;--white:#fff;--ink:#000;color-scheme:light;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
*{box-sizing:border-box}
html,body{margin:0;min-height:100%}
body{font-family:'Montserrat',system-ui,sans-serif;color:var(--ink);background:linear-gradient(135deg,var(--blue),var(--pink) 55%,var(--yellow));background-attachment:fixed;overflow-x:hidden;transition:filter 1s,background 1s}
body.sad{background:linear-gradient(160deg,#b9c0c8,#d3d6da 60%,#e4e4e6)}
h1,h2,h3{font-weight:700;margin:.3em 0}
em{font-style:italic;font-weight:600}
main{min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;position:relative;z-index:2}
.screen{display:none;width:100%;max-width:880px;background:rgba(255,255,255,.85);border-radius:28px;padding:32px 26px;text-align:center;box-shadow:0 12px 40px rgba(0,0,0,.08);backdrop-filter:blur(6px)}
.screen.show{display:block;animation:in .6s cubic-bezier(.2,.8,.2,1)}
@keyframes in{from{opacity:0;transform:translateY(24px) scale(.97)}to{opacity:1;transform:none}}
.big{font-size:64px;display:inline-block;animation:float 3s ease-in-out infinite}
@keyframes float{50%{transform:translateY(-10px) rotate(4deg)}}
.lead{font-size:1.05rem;line-height:1.6;max-width:560px;margin:10px auto 22px}
.row{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
button,.btn{font-family:inherit;font-weight:700;font-size:1rem;color:var(--ink);border:2px solid var(--ink);border-radius:999px;padding:13px 26px;cursor:pointer;text-decoration:none;display:inline-block;transition:transform .15s,box-shadow .15s;box-shadow:3px 3px 0 var(--ink)}
button:hover,.btn:hover{transform:translate(-2px,-2px) scale(1.04);box-shadow:5px 5px 0 var(--ink)}
button:active,.btn:active{transform:translate(2px,2px);box-shadow:0 0 0 var(--ink)}
.yes{background:var(--pink)}.no{background:var(--blue)}.go{background:var(--yellow)}.alt{background:var(--white)}
.sticker{background:var(--yellow);border:2px dashed var(--ink);border-radius:20px;padding:14px 18px;margin:16px auto;max-width:520px;transform:rotate(-1.5deg)}
.layout{display:grid;grid-template-columns:1.1fr 1fr;gap:20px;text-align:left}
@media(max-width:720px){.layout{grid-template-columns:1fr}.screen{padding:24px 16px}}
.cal{background:var(--white);border-radius:20px;padding:14px;border:2px solid var(--ink)}
.cal h3{text-align:center}
.grid{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}
.dow{font-size:.7rem;font-weight:700;text-align:center;padding:4px 0}
.d{aspect-ratio:1;border:1.5px solid var(--ink);border-radius:12px;background:var(--blue);font-size:.85rem;padding:2px;box-shadow:none;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.1}
.d span{font-size:.95rem}
.d:hover{transform:scale(1.1);box-shadow:none}
.d.c1{background:var(--pink)}.d.c2{background:var(--yellow)}.d.c3{background:var(--white)}
.d.sel{outline:3px solid var(--ink);transform:scale(1.1)}
.d.off{opacity:.4;cursor:not-allowed;background:#e5e5e5}
.d.blocked{background:#e5e5e5;opacity:.75}
.d.blank{visibility:hidden}
.panel{background:var(--white);border:2px solid var(--ink);border-radius:20px;padding:18px;min-height:260px}
.panel p{margin:.5em 0;line-height:1.5;font-size:.93rem}
.chips{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 14px}
.chip{padding:8px 14px;font-size:.82rem;box-shadow:2px 2px 0 var(--ink);background:var(--blue)}
.chip.sel{background:var(--pink)}
.mute{position:fixed;top:calc(12px + env(safe-area-inset-top,0px));right:12px;z-index:5;padding:8px 12px;font-size:.9rem;background:var(--white)}
#confetti{position:fixed;inset:0;pointer-events:none;z-index:9}
.cloud{position:fixed;top:0;left:-30%;width:220px;height:70px;background:#8d949c;border-radius:60px;opacity:0;z-index:1;filter:blur(2px)}
.cloud::before,.cloud::after{content:"";position:absolute;background:inherit;border-radius:50%}
.cloud::before{width:90px;height:90px;top:-40px;left:30px}.cloud::after{width:70px;height:70px;top:-28px;left:100px}
body.sad .cloud{animation:drift linear infinite}
@keyframes drift{0%{transform:translateX(0);opacity:.85}100%{transform:translateX(160vw);opacity:.85}}
.rain i{position:fixed;top:-20px;width:2px;height:14px;background:#6b737b;opacity:0;z-index:1}
body.sad .rain i{animation:rain linear infinite}
@keyframes rain{0%{transform:translateY(0);opacity:.7}100%{transform:translateY(110vh);opacity:.7}}
.blocked-box{text-align:center}
.pic{display:block;max-width:min(100%,270px);width:100%;height:auto;margin:0 auto 12px;border-radius:24px;border:2px solid var(--ink);box-shadow:5px 5px 0 var(--ink);animation:float 4s ease-in-out infinite}.panel .pic{max-width:240px;animation:none}.inp{font-family:inherit;font-size:.95rem;color:var(--ink);background:var(--white);border:2px solid var(--ink);border-radius:999px;padding:12px 18px;width:100%;max-width:460px;margin:0 auto 14px;display:block;box-shadow:3px 3px 0 var(--ink);outline:none}.inp:focus{background:var(--yellow)}.home{margin-top:6px;font-size:.9rem;padding:10px 20px}
</style>
</head>
<body>
<button class="mute alt" id="mute" aria-label="Sonido">🔊</button>
<canvas id="confetti"></canvas>
<div id="clouds"></div><div class="rain" id="rain"></div>

<main>
<section class="screen show" id="s1">
  <img class="pic" src="data:image/jpeg;base64," alt="Pato preguntando: ¿Salimos?">
  <h1>Una cita pendiente</h1>
  <p class="lead"><em>Señor, tenemos una cita pendiente.</em> Debido a su falta de disponibilidad, se le solicita confirmar si desea agendar un encuentro conmigo.</p>
  <p class="lead" style="font-size:.85rem;margin-top:-10px"><em>(Su agenda, según usted, está muy ocupada.)</em></p>
  <div class="row">
    <button class="yes" id="yes">¡Sí, agendemos! 💖</button>
    <button class="no" id="no">No puedo 🥲</button>
  </div>
</section>

<section class="screen" id="s2">
  <img class="pic" src="data:image/jpeg;base64," alt="Peluche triste">
  <h1>Ah bueno, gracias</h1>
  <div class="sticker"><em>Intentar agendar una cita con usted es como pedir un bus en hora pico: siempre pasa lleno. 🚌</em></div>
  <p class="lead">Sin presión, señor. La invitación queda abierta por si su agenda se apiada.</p>
  <p class="lead" style="margin-bottom:10px"><em>Si desea, cuéntele el motivo a la señorita Sara:</em></p>
  <input class="inp" id="motivo" type="text" maxlength="140" placeholder="Ej: tengo reunión con mi agenda 📅">
  <div class="row"><button class="no" id="nowa">Avisar por WhatsApp 💬</button><button class="go" id="again">Mejor sí, revisé mi agenda 👀</button><button class="alt home">← Volver al inicio</button></div>
</section>

<section class="screen" id="s3">
  <img class="pic" src="data:image/jpeg;base64," alt="Mono contestando el teléfono">
  <h1>¡Excelente decisión!</h1>
  <p class="lead">Muchas gracias, <em>señor Mateo</em>. Ahora agendaremos una fecha y el tipo de cita que tendrá.</p>
  <div class="row"><button class="go" id="cont">Continuar →</button><button class="alt home">← Volver al inicio</button></div>
</section>

<section class="screen" id="s4">
  <h2>Elija su fecha, <em>señor Mateo</em></h2>
  <p class="lead" style="margin:0 auto 16px;font-size:.9rem">Cada día trae un plan diferente. Toque uno para ver los detalles.</p>
  <div class="layout">
    <div class="cal"><h3>Noviembre 2026</h3><div class="grid" id="grid"></div></div>
    <div class="panel" id="panel"><p><em>Seleccione una fecha en el calendario ✨</em></p></div>
  </div>
  <div style="margin-top:18px"><p class="lead" style="margin:0 auto 10px;font-size:.9rem"><em>¿Prefiere otro plan u otra fecha? Haga su propia propuesta:</em></p><input class="inp" id="propuesta" type="text" maxlength="160" placeholder="Ej: el sábado 14 en la tarde, plan sorpresa"></div><div class="row"><button class="alt home">← Volver al inicio</button><button class="yes" id="propose">Nueva propuesta 💡</button></div>
</section>
</main>

<script>
const $=s=>document.querySelector(s);
let muted=false,ac;
function ctx(){try{ac=ac||new (window.AudioContext||window.webkitAudioContext)();if(ac.state==='suspended')ac.resume();return ac}catch(e){return null}}
function tone(f,t=0,d=.25,type='sine',v=.15){if(muted)return;const a=ctx();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.value=f;const s=a.currentTime+t;g.gain.setValueAtTime(0,s);g.gain.linearRampToValueAtTime(v,s+.02);g.gain.exponentialRampToValueAtTime(.001,s+d);o.connect(g).connect(a.destination);o.start(s);o.stop(s+d+.05)}
const click=()=>tone(660,0,.12,'triangle',.12);
const happy=()=>[523,659,784,1047,1319].forEach((f,i)=>tone(f,i*.11,.35,'triangle',.18));
const sad=()=>[440,415,392,330,349,294,262].forEach((f,i)=>tone(f,i*.55,.9,'sine',.16));
document.addEventListener('click',e=>{if(e.target.closest('button,.btn'))click()},true);
$('#mute').onclick=()=>{muted=!muted;$('#mute').textContent=muted?'🔇':'🔊'};

function show(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('show'));$(id).classList.add('show');scrollTo({top:0,behavior:'smooth'})}
function setSad(on){document.body.classList.toggle('sad',on)}
(function(){let c='';for(let i=0;i<5;i++)c+=`<div class="cloud" style="top:${5+i*13}vh;animation-duration:${18+i*5}s;animation-delay:-${i*4}s;transform:scale(${.8+i*.2})"></div>`;$('#clouds').innerHTML=c;let r='';for(let i=0;i<40;i++)r+=`<i style="left:${Math.random()*100}vw;animation-duration:${.8+Math.random()*.8}s;animation-delay:-${Math.random()*2}s"></i>`;$('#rain').innerHTML=r})();

/* Confetti */
const cv=$('#confetti'),cx=cv.getContext('2d');let parts=[],raf;
function size(){cv.width=innerWidth;cv.height=innerHeight}size();addEventListener('resize',size);
function confetti(){const cols=['#cfe6ff','#ffd1e3','#fff3b8','#ffffff','#ff9fc4','#9ccbff'];parts=[];for(let i=0;i<180;i++)parts.push({x:innerWidth/2,y:innerHeight/2.2,vx:(Math.random()-.5)*16,vy:Math.random()*-14-4,w:6+Math.random()*7,h:4+Math.random()*6,r:Math.random()*6,vr:(Math.random()-.5)*.4,c:cols[i%cols.length],l:1});cancelAnimationFrame(raf);(function f(){cx.clearRect(0,0,cv.width,cv.height);parts.forEach(p=>{p.vy+=.28;p.x+=p.vx;p.y+=p.vy;p.vx*=.99;p.r+=p.vr;p.l-=.004;cx.save();cx.globalAlpha=Math.max(p.l,0);cx.translate(p.x,p.y);cx.rotate(p.r);cx.fillStyle=p.c;cx.strokeStyle='#000';cx.lineWidth=.6;cx.fillRect(-p.w/2,-p.h/2,p.w,p.h);cx.strokeRect(-p.w/2,-p.h/2,p.w,p.h);cx.restore()});parts=parts.filter(p=>p.l>0&&p.y<cv.height+20);if(parts.length)raf=requestAnimationFrame(f);else cx.clearRect(0,0,cv.width,cv.height)})()}

document.querySelectorAll('.home').forEach(b=>b.onclick=()=>{setSad(false);show('#s1')});
const WA='https://wa.me/573043798227?text=';
$('#nowa').onclick=()=>{const m=$('#motivo').value.trim()||'falta de disponibilidad en mi agenda';window.open(WA+encodeURIComponent(`Cordial saludo, señorita Sara. Lamentablemente no podré aceptar esta gran oferta por ${m}.`),'_blank','noopener')};
$('#propose').onclick=()=>{const p=$('#propuesta').value.trim();const t=p?`Cordial saludo, señorita Sara. Espero que se encuentre muy bien. Quisiera hacerle una nueva propuesta para salir: ${p}. Quedo atento a su respuesta. Feliz día.`:'Cordial saludo, señorita Sara. Espero que se encuentre muy bien. Quisiera hacerle una nueva propuesta para salir. ¿Podemos coordinar otra fecha y plan? Quedo atento a su respuesta. Feliz día.';window.open(WA+encodeURIComponent(t),'_blank','noopener')};
$('#yes').onclick=()=>{setSad(false);show('#s3');happy();confetti()};
$('#no').onclick=()=>{setSad(true);show('#s2');sad()};
$('#again').onclick=()=>{setSad(false);show('#s3');happy();confetti()};
$('#cont').onclick=()=>{show('#s4');drawCal()};

/* Plans */
const IMG4="data:image/jpeg;base64,";
const IC='🍦', HEL={t:'Helado en Crepes & Waffles',e:'🍦',c:1,d:'Un helado rico en Crepes & Waffles, para endulzar la conversación.',tr:'Se define entre los dos según el sitio más cómodo.'};
const MON=HEL,
CINE={t:'Noche de cine',e:'🎬',c:3,d:'Función de cine en la noche, con crispetas incluidas (negociables).',tr:'Se define entre los dos según el cine elegido.'},
GAME={t:'Plan de videojuegos',e:'🎮',c:2,d:'Noche de videojuegos: retos, risas y revancha asegurada.',tr:'Se define entre los dos según el lugar.'},
DET={t:'Viernes de “Detective Case File”',e:'🕵️',c:1,d:'Compran un juego de misterio de mesa o un kit de archivos de investigación. Piden una pizza, apagan las luces, ponen música de suspenso y se dedican a analizar pistas y debatir quién fue el culpable.',tr:'En casa, perfecto para desconectarse de la semana.'},
TED={t:'Viernes de “TED Talk casera”',e:'🎤',c:2,d:'Cada uno prepara una mini presentación de 10–15 minutos sobre un tema que le apasione, para enseñárselo al otro (un hobby, un tema friki, algo de su carrera o una teoría locochona). Con snacks y algo de tomar.',tr:'En casa.'},
BOT={t:'Picnic “Zero-Grass” + tarde de crochet y café en el Jardín Botánico',e:'🧶',c:3,d:'Caminan por los senderos adoquinados y puentes del Jardín Botánico (entrada gratis). Buscan una mesa de madera o una banca cómoda (nada de sentarse en el pasto) para armar una lonchera con snacks ricos de comer con las manos. Luego sacan los materiales y le enseñas la clase de crochet mientras toman algo.',tr:'En Metro: estación Envigado y bajan en Universidad (al frente). Cero estrés de tráfico.'},
SAL={t:'Café campestre en El Salado (Envigado)',e:'☕',c:2,d:'Subir a la parte alta de Envigado a buscar una cafetería de origen o un café campestre. Clima fresco de montaña sin irse muy lejos, aire puro y tardear con un café especial o un chocolate.',tr:'En carro desde el parque de Envigado (aprox. 15–20 min) o en el bus integrado que sube hacia El Salado.'},
STA={t:'Escapada a Santa Elena: café de montaña',e:'🌲',c:1,d:'Manejar hasta el corregimiento de Santa Elena para visitar una cafetería metida entre pinos, disfrutar de la neblina, caminar un rato por los viveros y comer repostería artesanal con un buen café caliente.',tr:'En carro (o moto): por Las Palmas y desvío hacia Santa Elena. El trayecto es precioso.'};
const sun=(t,e,x)=>({t:'Helado en Crepes & Waffles + '+t,e,c:1,d:'Helado en Crepes & Waffles y, además, un plan tranquilo: '+x,tr:'Se define entre los dos según el plan.'});
const SUN={15:sun('ciclovía','🚲','paseo por la ciclovía.'),22:sun('bolos','🎳','una partida de bolos.'),29:sun('película en casa','🍿','película en casa con snacks.')};
const FRI={6:DET,13:TED,20:DET,27:TED},SAT={7:BOT,14:SAL,21:STA,28:BOT};
const BLOCKED=[8,19],DAYS=['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const planFor=n=>{const w=new Date(2026,10,n).getDay();return w==1?HEL:(w==2||w==3)?CINE:w==4?GAME:w==5?FRI[n]:w==6?SAT[n]:SUN[n]};
function slots(n){const w=new Date(2026,10,n).getDay();
 if(w==6)return[['Mañana (9 am – 12 m)',[9,12]],['Tarde (2 pm – 6 pm)',[14,18]],['Todo el día (9 am – 6 pm)',[9,18]]];
 if(w==0)return[['Mañana (9 – 11 am)',[9,11]],['Noche (5 – 9 pm)',[17,21]]];
 return[['Noche (6 – 9 pm)',[18,21]]]}

let selDay=null,selSlot=0;
function drawCal(){const g=$('#grid');g.innerHTML=['D','L','M','M','J','V','S'].map(d=>`<div class="dow">${d}</div>`).join('');
 const first=new Date(2026,10,1).getDay();for(let i=0;i<first;i++)g.innerHTML+='<div class="d blank"></div>';
 for(let n=1;n<=30;n++){const p=planFor(n),bl=BLOCKED.includes(n),past=n<3;
  g.innerHTML+=`<button class="d ${bl?'blocked':past?'off':'c'+p.c}" data-n="${n}" ${past?'disabled':''}><span>${n}</span>${bl?'🚫':p?p.e:''}</button>`}
 g.onclick=e=>{const b=e.target.closest('.d[data-n]');if(!b||b.disabled)return;pick(+b.dataset.n)}}
function pick(n){selDay=n;selSlot=0;document.querySelectorAll('.d.sel').forEach(x=>x.classList.remove('sel'));document.querySelector(`.d[data-n="${n}"]`).classList.add('sel');render()}
function render(){const n=selDay,P=$('#panel'),dn=DAYS[new Date(2026,10,n).getDay()];
 if(BLOCKED.includes(n)){P.innerHTML=`<div class="blocked-box"><img class="pic" src="${IMG4}" alt="Mono: fecha no disponible"><h3>Fecha inhabilitada</h3><div class="sticker"><em>Agenda del señor: ¡OCUPADO! 🙅‍♂️</em></div><p><em>Fecha inhabilitada, por favor seleccione otra fecha.</em></p></div>`;return}
 const p=planFor(n),sl=slots(n),s=sl[selSlot],pad=x=>String(x).padStart(2,'0'),date=`${dn} ${n} de noviembre`;
 const txt=`${p.t}`,st=`202611${pad(n)}T${pad(s[1][0])}0000`,en=`202611${pad(n)}T${pad(s[1][1])}0000`;
 const gc='https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent('Cita con Sara: '+txt)+'&dates='+st+'/'+en+'&details='+encodeURIComponent(p.d+'\nTransporte: '+p.tr)+'&add='+encodeURIComponent('mateoz4P4T4@gmail.com')+'&ctz=America/Bogota';
 const msg=`Cordial Saludo. Espero que se encuentre muy bien señorita Sara. Me gustaría confirmar la cita para la fecha ${date} de 2026 (${txt}, ${s[0]}), espero con ansias esa fecha. Muchas gracias. Feliz día.`;
 const wa='https://wa.me/573043798227?text='+encodeURIComponent(msg);
 P.innerHTML=`<h3>${p.e} Plan de la cita</h3><p><em>${date}</em></p><p><b>${p.t}</b></p><p>${p.d}</p><p><b>Transporte:</b> ${p.tr}</p><p><b>Hora:</b></p><div class="chips">${sl.map((x,i)=>`<button class="chip ${i==selSlot?'sel':''}" data-i="${i}">${x[0]}</button>`).join('')}</div><div class="row"><a class="btn go" target="_blank" rel="noopener" href="${gc}">📅 Agendar</a><a class="btn yes" target="_blank" rel="noopener" href="${wa}">✅ Confirmar cita</a></div>`;
 P.querySelectorAll('.chip').forEach(c=>c.onclick=()=>{selSlot=+c.dataset.i;render()})}
</script>
</body>
</html>
"""


class Manejador(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        datos = HTML.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(datos)))
        self.end_headers()
        self.wfile.write(datos)

    def log_message(self, *args):
        pass


if __name__ == "__main__":
    socketserver.TCPServer.allow_reuse_address = True
    with socketserver.TCPServer(("127.0.0.1", PUERTO), Manejador) as servidor:
        url = f"http://127.0.0.1:{PUERTO}"
        print(f"Invitación lista en {url}  (Ctrl + C para cerrar)")
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
        try:
            servidor.serve_forever()
        except KeyboardInterrupt:
            print("\nCerrado. ¡Suerte con la cita! 💖")
